        assigns=[]
        anns=[]
        for n in ast.walk(fn):
            if isinstance(n, ast.Assign):
                for t in n.targets:
                    if isinstance(t, ast.Name): assigns.append((t.id,n.lineno))
                    elif isinstance(t, (ast.Tuple,ast.List)):
                        assigns.extend((e.id,n.lineno) for e in t.elts if isinstance(e,ast.Name))
            elif isinstance(n, ast.AnnAssign) and isinstance(n.target, ast.Name):
                anns.append((n.target.id,n.lineno))
        if assigns:
            print(f'  {fn.name}: unannotated={assigns} annotated={anns}')
